type Activity={id:string;type:'choice'|'input'|'order';prompt:string;options?:string[];answer:string|string[];explanation:string;placeholder?:string};
export type DecimalStage={id:string;title:string;eyebrow:string;kind:'story'|'model'|'guided'|'practice'|'quiz'|'challenge'|'summary';body:string;note?:string;sourceTag?:string;activity?:Activity};
type Saved={version:1;stageIndex:number;answer:string;ordered:string[];checked:boolean;correct:boolean;results:Record<string,boolean>;completedAt?:string};
const KEY='mathnikita-lesson-3-progress-v1';

